let windowSize = 30m;

// S106: Flocking Parameter Tamper — UAVFleetState_CL, FleetId 사용, DivergingCount로 대형이탈 대리 탐지
let S106 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where DivergingCount > 2
    | extend Stage = 'S106', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S103: Collision Course — CollisionRiskPair 존재
let S103 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(CollisionRiskPair)
    | extend Stage = 'S103', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S108: Mesh Partition — UAVFleetInfra_CL, FleetId 사용
let S108 =
    UAVFleetInfra_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(LinkA) and isnotempty(LinkB) and LinkStatus != 'up'
    | extend Stage = 'S108', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S106, S103, S108
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| where StageCount >= 2
| extend CampaignType = "C28_물리파괴_flocking변조_충돌유도_메시분단"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
